# Transparent triage score: easy to audit and tune.
IMPACT = {"low": 1, "medium": 2, "high": 3}
CRITICAL_ASSETS = {"dc01", "erp-db", "vpn-gw"}

def priority(impact, active, asset, regulated_data=False, privileged=False):
    score = IMPACT[impact] + (2 if active else 0)
    if asset in CRITICAL_ASSETS:
        score += 1
    if regulated_data or privileged:
        score += 2          # these two always push the incident up
    return "P1" if score >= 6 else "P2" if score >= 5 else "P3" if score >= 3 else "P4"

print(priority("medium", True, "fin-lt-07", privileged=True))  # P1
print(priority("low", False, "lab-03"))                        # P4

